        vault.offsetDebt(_amount, msg.sender);
        //vault.transferValue(_amount, msg.sender);
        _compensated = _amount;
    } else {
        //Withdraw credit to cashout the earnings
        uint256 _shortage;
        if (totalLiquidity() < _amount) {
